ALTER TABLE public.profiles ADD COLUMN mail_test boolean NOT NULL DEFAULT false, ADD COLUMN mail_opt_out_at timestamptz, ADD COLUMN mail_language text NOT NULL DEFAULT 'en' CHECK (mail_language IN ('en','sv'));
GRANT UPDATE(mail_opt_out_at,mail_language) ON public.profiles TO authenticated;
CREATE FUNCTION public.guard_mail_test() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.mail_test IS DISTINCT FROM OLD.mail_test AND auth.role() IS DISTINCT FROM 'service_role' AND NOT public.has_role(auth.uid(),'admin') AND session_user NOT IN ('postgres','supabase_admin') THEN RAISE EXCEPTION 'Only admins may mark mail test accounts' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
CREATE TRIGGER profiles_guard_mail_test BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.guard_mail_test();
CREATE TABLE public.mail_templates(key text PRIMARY KEY CHECK(key IN ('first_request_nudge','connect_garage_nudge','garage_offline')), enabled boolean NOT NULL DEFAULT true, subject_en text NOT NULL,body_en text NOT NULL,subject_sv text NOT NULL,body_sv text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.mail_templates TO authenticated;
GRANT ALL ON public.mail_templates TO service_role;
ALTER TABLE public.mail_templates ENABLE ROW LEVEL SECURITY;
CREATE POLICY mail_templates_admin ON public.mail_templates FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.mail_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,template_key text NOT NULL,event_ref text NOT NULL DEFAULT '',mode text NOT NULL CHECK(mode IN ('off','test','on')),status text NOT NULL CHECK(status IN ('sent','failed','skipped_cap','skipped_opt_out')),provider_message_id text,error text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.mail_log TO authenticated;
GRANT ALL ON public.mail_log TO service_role;
ALTER TABLE public.mail_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY mail_log_admin ON public.mail_log FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX mail_log_sent_event ON public.mail_log(user_id,template_key,event_ref) WHERE status='sent';
CREATE INDEX mail_log_created ON public.mail_log(created_at DESC);
CREATE INDEX mail_log_user_created ON public.mail_log(user_id,created_at DESC);
CREATE TABLE public.mail_delivery_state(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,total_sent integer NOT NULL DEFAULT 0 CHECK(total_sent>=0),recent_sent timestamptz[] NOT NULL DEFAULT '{}',sent_events jsonb NOT NULL DEFAULT '{}');
GRANT ALL ON public.mail_delivery_state TO service_role;
ALTER TABLE public.mail_delivery_state ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.mail_worker_lock(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),owner uuid NOT NULL,until_at timestamptz NOT NULL);
GRANT ALL ON public.mail_worker_lock TO service_role;
ALTER TABLE public.mail_worker_lock ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.set_mail_test(_user_id uuid,_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; UPDATE public.profiles SET mail_test=_enabled WHERE id=_user_id; END $$;
REVOKE ALL ON FUNCTION public.set_mail_test(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_mail_test(uuid,boolean) TO authenticated;
CREATE FUNCTION public.event_mail_lock(_owner uuid,_release boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE got boolean; BEGIN IF _release THEN DELETE FROM public.mail_worker_lock WHERE singleton AND owner=_owner; RETURN true; END IF; INSERT INTO public.mail_worker_lock(singleton,owner,until_at) VALUES(true,_owner,now()+interval '10 minutes') ON CONFLICT(singleton) DO UPDATE SET owner=excluded.owner,until_at=excluded.until_at WHERE mail_worker_lock.until_at<now() RETURNING true INTO got; RETURN coalesce(got,false); END $$;
REVOKE ALL ON FUNCTION public.event_mail_lock(uuid,boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.event_mail_lock(uuid,boolean) TO service_role;
CREATE FUNCTION public.event_mail_stats() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.role() IS DISTINCT FROM 'service_role' AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF; RETURN jsonb_build_object('mode',coalesce((SELECT value->>'mode' FROM admin_settings WHERE key='event_mail'),'off'),'sent_7d',(SELECT count(*) FROM mail_log WHERE status='sent' AND created_at>=now()-interval '7 days'),'failed_7d',(SELECT count(*) FROM mail_log WHERE status='failed' AND created_at>=now()-interval '7 days'),'by_template',(SELECT coalesce(jsonb_object_agg(t.key,jsonb_build_object('sent_30d',(SELECT count(*) FROM mail_log l WHERE l.template_key=t.key AND l.status='sent' AND l.created_at>=now()-interval '30 days'))),'{}'::jsonb) FROM mail_templates t),'opted_out',(SELECT count(*) FROM profiles WHERE mail_opt_out_at IS NOT NULL)); END $$;
REVOKE ALL ON FUNCTION public.event_mail_stats() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.event_mail_stats() TO authenticated,service_role;